#!/usr/bin/env bash
# DOC — extraits de code situés dans leur fichier :
#   - numéros de ligne RÉELS du fichier (les passages sautés restent sans numéro) ;
#   - bouton « Voir le fichier complet » : le fichier entier, extraits de la page surlignés ;
#   - barre latérale « Extraits de ce fichier » pour passer d'un extrait à l'autre du même fichier ;
#   - un extrait introuvable dans son fichier garde l'affichage simple (coloré, chemin en en-tête).
# Prérequis : apply-docs-code-dark.sh.
# Usage (racine du repo) : bash apply-docs-code-fichier.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/docs/[...slug]/page.tsx" 2>/dev/null | grep -qF "buildFenceIndex"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "MdxCodeFence" "apps/web/src/mdx-components.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-code-dark.sh"; exit 1; }
MODIFIED=("apps/web/src/app/docs/[...slug]/page.tsx" "apps/web/src/features/docs/lib/code.utils.ts" "apps/web/src/features/docs/ui/MdxCodeFence.tsx")
CREATED=("apps/web/src/features/docs/lib/fenceIndex.ts" "apps/web/src/features/docs/lib/snippetLocate.ts" "apps/web/src/features/docs/ui/CodeFenceClient.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "buildFenceIndex" "apps/web/src/app/docs/[...slug]/page.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/lib"
